# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: gather
def gather(xs):
    return [v for v in xs if v % 2 == 0]

# region: digest
def digest(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs):
    return {'n': len(xs) - 1, 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: sift
def sift(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return sift(intake(digest(gather(render(raw)))))

